export function validateSummaryAmounts(item: EnrollmentItem, areaMu: string | number): string[] {
  const area = toScaledInteger(areaMu, AREA_SCALE)
  if (area === null) return ['面积格式非法']
  const sumInsured = Math.round(area * UNIT_SUM_INSURED_CENTS_PER_MU / AREA_SCALE)
  const premium = Math.round(sumInsured * 32 / 1000)
  const subsidy = Math.round(premium * 80 / 100)
  const selfPaid = premium - subsidy
  const errors: string[] = []
  if (item.sum_insured_cents !== sumInsured) errors.push('保额汇总不一致')
  if (item.premium_cents !== premium) errors.push('保费汇总不一致')
  if (item.subsidy_cents !== subsidy) errors.push('补贴汇总不一致')
  if (item.self_paid_cents !== selfPaid) errors.push('自缴汇总不一致')
  return errors
}

